class BytesIOCopy(io.BytesIO):
    """Patch ``io.BytesIO`` to let the written stream be copied to another.

    .. versionadded:: 8.2

    .. versionchanged:: 8.3.3
        Added a real, file-descriptor backed ``fileno()`` implementation,
        created lazily on first use, so instances can be passed as
        ``stdout``/``stderr`` to APIs such as :func:`subprocess.run` that
        require a real file descriptor. :issue:`2210`
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        super().__init__()
        self.copy_to = copy_to
        self._fd_file: t.BinaryIO | None = None

    def flush(self) -> None:
        if self._fd_file is not None:
            self._fd_file.flush()
        else:
            super().flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)

        if self._fd_file is not None:
            return self._fd_file.write(b)

        return super().write(b)

    def getvalue(self) -> bytes:
        if self._fd_file is not None:
            pos = self._fd_file.tell()
            self._fd_file.seek(0)
            data = self._fd_file.read()
            self._fd_file.seek(pos)
            return data

        return super().getvalue()

    def fileno(self) -> int:
        """Return a real file descriptor, backed by a temporary file.

        The descriptor is created on first use so that instances not used
        with APIs requiring a real file descriptor keep behaving like a
        plain in-memory :class:`io.BytesIO`.
        """
        if self._fd_file is None:
            self._fd_file = tempfile.TemporaryFile()
            self._fd_file.write(super().getvalue())
            self._fd_file.flush()

        return self._fd_file.fileno()

    def close(self) -> None:
        if self._fd_file is not None:
            self._fd_file.close()

        super().close()


